CREATE ROW ACCESS POLICY IF NOT EXISTS SEC.RAP_ACTIVE_METER AS (p_location_id STRING, p_status STRING) RETURNS BOOLEAN -> TRUE
  COMMENT = 'From Cognos securityFilter ActiveMeterFilter on Meter; applies to Field_Technicians; exempt Report_Admins, Billing_Analysts';

ALTER ROW ACCESS POLICY SEC.RAP_ACTIVE_METER SET BODY ->
    IS_ROLE_IN_SESSION('BILLING_ANALYSTS') OR IS_ROLE_IN_SESSION('REPORT_ADMINS')
    OR (p_status = 'Active' AND EXISTS (SELECT 1 FROM RAW_ENERGY_DW.LOCATION x WHERE x.LOCATION_ID = p_location_id AND x.REGION IN (SELECT m.REGION FROM SEC.MAP_USER_REGION m WHERE m.USERNAME = CURRENT_USER())));

ALTER ROW ACCESS POLICY SEC.RAP_ACTIVE_METER SET COMMENT = 'From Cognos securityFilter ActiveMeterFilter on Meter; applies to Field_Technicians; exempt Report_Admins, Billing_Analysts';
